(() => {
  function daysOfCover(stock, sellOut, weeks) {
    const w = typeof weeks === "number" && weeks > 0 ? weeks : 4;
    const s = Number(stock);
    const so = Number(sellOut);
    if (!(so > 0)) return Infinity;
    if (!Number.isFinite(s)) return NaN;
    return s * w * 7 / so;
  }
  function createAlerter() {
    const sent = new Set();
    function check({ distributor, sku, stock, sellOut, weeks, date } = {}) {
      const cover = daysOfCover(stock, sellOut, weeks);
      if (!Number.isFinite(cover) || cover > 7) return null;
      const key = JSON.stringify([distributor, sku, date]);
      if (sent.has(key)) return null;
      sent.add(key);
      return { distributor, sku, cover };
    }
    return { check };
  }
  return { daysOfCover, createAlerter };
})()

