unitScript:
test("days of cover is 6 for 120 units in stock and 560 units sold over 4 weeks", () => {
  assert.equal(code.daysOfCover(120, 560, 4), 6);
});
test("alert is sent with cover 6 when cover is 6 days", () => {
  const a = code.createAlerter();
  assert.deepEqual(a.check({ distributor: "D1", sku: "P1", stock: 120, sellOut: 560, weeks: 4, date: "2024-05-01" }), { distributor: "D1", sku: "P1", cover: 6 });
});
test("alert is sent when cover is exactly 7 days and not sent at 8 days", () => {
  const a = code.createAlerter();
  assert.deepEqual(a.check({ distributor: "D1", sku: "P1", stock: 140, sellOut: 560, weeks: 4, date: "2024-05-01" }), { distributor: "D1", sku: "P1", cover: 7 });
  assert.equal(code.daysOfCover(160, 560, 4), 8);
  assert.equal(a.check({ distributor: "D2", sku: "P1", stock: 160, sellOut: 560, weeks: 4, date: "2024-05-01" }), null);
});
test("only one alert per distributor and product on the same day, and a new one the next day", () => {
  const a = code.createAlerter();
  const input = { distributor: "D1", sku: "P1", stock: 120, sellOut: 560, weeks: 4 };
  assert.ok(a.check({ ...input, date: "2024-05-01" }));
  assert.equal(a.check({ ...input, date: "2024-05-01" }), null);
  assert.deepEqual(a.check({ ...input, date: "2024-05-02" }), { distributor: "D1", sku: "P1", cover: 6 });
});
test("a different product for the same distributor on the same day still gets its own alert", () => {
  const a = code.createAlerter();
  assert.ok(a.check({ distributor: "D1", sku: "P1", stock: 120, sellOut: 560, weeks: 4, date: "2024-05-01" }));
  assert.deepEqual(a.check({ distributor: "D1", sku: "P2", stock: 120, sellOut: 560, weeks: 4, date: "2024-05-01" }), { distributor: "D1", sku: "P2", cover: 6 });
});
test("zero sell-out gives infinite cover, no alert and no error", () => {
  assert.equal(code.daysOfCover(50, 0, 4), Infinity);
  const a = code.createAlerter();
  let result;
  result = a.check({ distributor: "D1", sku: "P1", stock: 50, sellOut: 0, weeks: 4, date: "2024-05-01" });
  assert.equal(result, null);
});

