test("days of cover is stock on hand divided by average daily sell-out from the last 4 weeks and an alert is sent when cover is 7 or less", function() {
  assert.equal(560 / 28, 20);
  assert.equal(120 / 20, 6);
  assert.equal(code.daysOfCover(120, 560, 4), 6);
  var alerter = code.createAlerter();
  var alert = alerter.check({
    distributor: "D1",
    sku: "P1",
    stock: 120,
    sellOut: 560,
    weeks: 4,
    date: "2024-06-01"
  });
  assert.deepEqual(alert, { distributor: "D1", sku: "P1", cover: 6 });
});
test("alert when days of cover is exactly 7", function() {
  assert.equal(140 / 20, 7);
  assert.equal(code.daysOfCover(140, 560, 4), 7);
  var alerter = code.createAlerter();
  var alert = alerter.check({
    distributor: "D2",
    sku: "P2",
    stock: 140,
    sellOut: 560,
    weeks: 4,
    date: "2024-06-02"
  });
  assert.deepEqual(alert, { distributor: "D2", sku: "P2", cover: 7 });
});
test("no alert when days of cover is above 7", function() {
  assert.equal(160 / 20, 8);
  assert.equal(code.daysOfCover(160, 560, 4), 8);
  var alerter = code.createAlerter();
  var alert = alerter.check({
    distributor: "D3",
    sku: "P3",
    stock: 160,
    sellOut: 560,
    weeks: 4,
    date: "2024-06-03"
  });
  assert.equal(alert, null);
});
test("at most one alert per distributor per product per day", function() {
  var alerter = code.createAlerter();
  var date = "2024-06-04";
  var a1 = alerter.check({ distributor: "D4", sku: "A", stock: 120, sellOut: 560, weeks: 4, date });
  var a2 = alerter.check({ distributor: "D4", sku: "A", stock: 120, sellOut: 560, weeks: 4, date });
  var b1 = alerter.check({ distributor: "D4", sku: "B", stock: 140, sellOut: 560, weeks: 4, date });
  var b2 = alerter.check({ distributor: "D4", sku: "B", stock: 140, sellOut: 560, weeks: 4, date });
  assert.deepEqual(a1, { distributor: "D4", sku: "A", cover: 6 });
  assert.equal(a2, null);
  assert.deepEqual(b1, { distributor: "D4", sku: "B", cover: 7 });
  assert.equal(b2, null);
});
test("a qualifying distributor and product may alert again on the next day", function() {
  var alerter = code.createAlerter();
  var day1 = alerter.check({ distributor: "D5", sku: "A", stock: 120, sellOut: 560, weeks: 4, date: "2024-06-05" });
  var day1Again = alerter.check({ distributor: "D5", sku: "A", stock: 120, sellOut: 560, weeks: 4, date: "2024-06-05" });
  var day2 = alerter.check({ distributor: "D5", sku: "A", stock: 120, sellOut: 560, weeks: 4, date: "2024-06-06" });
  var day2Again = alerter.check({ distributor: "D5", sku: "A", stock: 120, sellOut: 560, weeks: 4, date: "2024-06-06" });
  assert.deepEqual(day1, { distributor: "D5", sku: "A", cover: 6 });
  assert.equal(day1Again, null);
  assert.deepEqual(day2, { distributor: "D5", sku: "A", cover: 6 });
  assert.equal(day2Again, null);
});
test("if 4-week sell-out is zero days of cover is undefined and no alert is sent and no error is raised", function() {
  assert.equal(code.daysOfCover(50, 0, 4), Infinity);
  var alerter = code.createAlerter();
  var alert = alerter.check({
    distributor: "D6",
    sku: "P6",
    stock: 50,
    sellOut: 0,
    weeks: 4,
    date: "2024-06-07"
  });
  assert.equal(alert, null);
});
test("in v1 a seasonal product follows the same rule and an alert is sent", function() {
  assert.equal(code.daysOfCover(120, 560, 4), 6);
  var alerter = code.createAlerter();
  var alert = alerter.check({
    distributor: "D7",
    sku: "SEASONAL-1",
    stock: 120,
    sellOut: 560,
    weeks: 4,
    date: "2024-06-08"
  });
  assert.deepEqual(alert, { distributor: "D7", sku: "SEASONAL-1", cover: 6 });
});
test("v1 covers all products and sends an alert with no fast-moving filter", function() {
  assert.equal(code.daysOfCover(120, 560, 4), 6);
  var alerter = code.createAlerter();
  var alert = alerter.check({
    distributor: "D8",
    sku: "SLOW-MOVER",
    stock: 120,
    sellOut: 560,
    weeks: 4,
    date: "2024-06-09"
  });
  assert.deepEqual(alert, { distributor: "D8", sku: "SLOW-MOVER", cover: 6 });
});

